import{G as e,V as t,W as n,n as r,rt as i}from"./chunks/framework.BR9-gX-M.js";var a=JSON.parse(`{"title":"Reading a report - automatica11y","description":"","frontmatter":{},"headers":[],"relativePath":"reports.md","filePath":"reports.md"}`),o={name:`reports.md`};function s(r,a,o,s,c,l){return i(),n(`div`,null,[...a[0]||=[e(`<h1 id="reading-a-report" tabindex="-1">Reading a report. <a class="header-anchor" href="#reading-a-report" aria-label="Permalink to “Reading a report.”">​</a></h1><p>Every run writes <code>report.md</code>, <code>results.json</code>, and <code>plan.json</code>. <code>report.md</code> is the one to read first. <code>results.json</code> has everything behind it.</p><h2 id="the-coverage-matrix" tabindex="-1">The coverage matrix. <a class="header-anchor" href="#the-coverage-matrix" aria-label="Permalink to “The coverage matrix.”">​</a></h2><p>A report opens with a matrix of target by archetype by tier. Each cell says what happened: <code>ran</code>, <code>gap</code>, <code>not-testable</code>, <code>not-applicable</code>, <code>skipped</code>, or <code>failed</code>. A gap, a failure, or a target that wasn&#39;t testable is a finding. It never counts as a pass.</p><h2 id="result-values" tabindex="-1">Result values. <a class="header-anchor" href="#result-values" aria-label="Permalink to “Result values.”">​</a></h2><p>Checks in the interactions, computed, and conditions tiers report one of these:</p>`,6),t(`div`,{class:`scroll`,role:`region`,tabindex:`0`,"aria-label":`Table: Result values`},[t(`table`,null,[t(`thead`,null,[t(`tr`,null,[t(`th`,null,`Result`),t(`th`,null,`Meaning`)])]),t(`tbody`,null,[t(`tr`,null,[t(`td`,null,[t(`code`,null,`pass`)]),t(`td`,null,`The check measured or observed what it looks for, and it held.`)]),t(`tr`,null,[t(`td`,null,[t(`code`,null,`fail`)]),t(`td`,null,`It didn't hold. The detail says what was measured and what was needed.`)]),t(`tr`,null,[t(`td`,null,[t(`code`,null,`undetermined`)]),t(`td`,null,`The check couldn't reduce the page to an answer, for example text over a gradient. It's a gap, never a pass.`)]),t(`tr`,null,[t(`td`,null,[t(`code`,null,`not-applicable`)]),t(`td`,null,`The page doesn't use the feature. A page with no dark theme has nothing to check in dark mode. That isn't a failure.`)]),t(`tr`,null,[t(`td`,null,[t(`code`,null,`error`)]),t(`td`,null,`The check couldn't finish. It's untested, not failed.`)])])])],-1),e(`<h2 id="findings-stay-separate" tabindex="-1">Findings stay separate. <a class="header-anchor" href="#findings-stay-separate" aria-label="Permalink to “Findings stay separate.”">​</a></h2><p>axe-core and IBM Equal Access findings are listed under their own names, and their counts are never added together. axe-core&#39;s <code>impact</code> and IBM&#39;s Toolkit level are different scales and aren&#39;t converted into each other. Computed checks and conditions checks are reported on their own as well, because they are automatica11y&#39;s own measurements.</p><h2 id="how-much-to-trust-a-result" tabindex="-1">How much to trust a result. <a class="header-anchor" href="#how-much-to-trust-a-result" aria-label="Permalink to “How much to trust a result.”">​</a></h2><p>Each target carries the kind of evidence it gave:</p><ul><li><strong>Component evidence</strong> comes from a fixture. An <strong>authored</strong> fixture, written from the library&#39;s documentation, is the strongest. A <strong>template</strong> (for <code>button</code> and <code>link</code>) is built from the export name. A <strong>generated</strong> fixture is a guess about how the library is assembled, so a failure may come from the wiring and not from the library. Reports mark generated results and the source is written to <code>generated/&lt;target id&gt;/</code> beside the report.</li><li><strong>Page evidence</strong> comes from testing a whole page.</li></ul><p>A comparison that mixes the two opens with a warning. The report also records the date, the tool versions, and the package versions, because results are a snapshot.</p><h2 id="wording" tabindex="-1">Wording. <a class="header-anchor" href="#wording" aria-label="Permalink to “Wording.”">​</a></h2><p>A report says &quot;no automated violations found&quot; only for an engine that reported none for that target. It never says &quot;accessible,&quot; &quot;compliant,&quot; or &quot;passes WCAG.&quot; It doesn&#39;t print a single score. If someone asks for a number, pair it with the coverage matrix and the limits.</p><p>Criterion names and levels come from the W3C&#39;s <a href="https://www.w3.org/WAI/WCAG22/wcag.json" target="_blank" rel="noreferrer">WCAG 2.2 JSON</a>, and every report credits the source in its closing section.</p>`,9)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};